person('selma', 'Selma Rain', 2600, 'city_warehouse', [2600, 5200, 11500, 20000],
    tr('Vermittlerin der Wasserhöfe', 'Mediator of the water courts', 'Mediadora de los patios de agua', 'Médiatrice des cours d’eau', 'Посредница водных дворов'),
    tr('Selma moderierte früher Sitzungen, deren Entscheidungen längst feststanden. Sie blieb, um auch denen zuzuhören, die nie eingeladen wurden. Jetzt sucht sie faire Gespräche, in denen Verantwortung und Widerspruch beide Platz haben.', 'Selma once chaired meetings with predetermined outcomes. She stayed to hear those who were never invited. Now she seeks fair conversations with room for both responsibility and disagreement.', 'Selma moderaba reuniones ya decididas. Se quedó para escuchar a quienes no eran invitados. Busca conversaciones justas con responsabilidad y desacuerdo.', 'Selma animait des réunions déjà décidées. Elle est restée écouter ceux qui n’étaient pas invités. Elle cherche des échanges laissant place à responsabilité et désaccord.', 'Сельма вела встречи с заранее решённым исходом. Она осталась слушать тех, кого не приглашали. Теперь ищет честные беседы с ответственностью и несогласием.'),
    tr('Ein Ja zählt nur, wenn auch ein Nein Platz hat.', 'A yes matters only when there is room for a no.', 'Un sí solo vale si hay sitio para un no.', 'Un oui compte seulement si un non a sa place.', 'Да имеет вес, только если есть место для нет.'), [
        step(tr('Der leere Stuhl', 'The empty chair', 'La silla vacía', 'La chaise vide', 'Пустой стул'), tr('Selma lässt einen Stuhl für abwesende Nachbarn frei. Ada liest ihre früheren Fragen, ohne Antworten zu erfinden.', 'Selma leaves a chair for absent neighbours. Ada reads their old questions without inventing answers.', 'Selma deja una silla. Ada lee preguntas antiguas sin inventar respuestas.', 'Selma laisse une chaise. Ada lit les anciennes questions sans inventer de réponses.', 'Сельма оставит стул отсутствующим. Ада прочитает их вопросы, не придумывая ответов.'), 'city_warehouse', 13, 9, 10),
        step(tr('Ein Nein am Blütenmarkt', 'A no at the Bloom Market', 'Un no en el mercado', 'Un non au marché des fleurs', 'Нет на Цветочном рынке'), tr('Viola widerspricht einem Vorschlag. Selma lässt die Begründung im Protokoll stehen, obwohl die Mehrheit anders entscheidet.', 'Viola disagrees with a proposal. Selma keeps her reason in the minutes even when the majority decides otherwise.', 'Viola discrepa. Selma conserva su razón aunque la mayoría decida distinto.', 'Viola conteste. Selma garde sa raison même si la majorité décide autrement.', 'Виола не согласится с предложением. Сельма сохранит причину, хотя большинство решит иначе.'), 'coffee_shop', 23, 5, 220),
        step(tr('Wo die leisen Stimmen bleiben', 'Where quiet voices remain', 'Donde quedan las voces suaves', 'Là où restent les voix discrètes', 'Где остаются тихие голоса'), tr('Jun fragt nach einem dauerhaften Erinnerungsort für offene Gespräche. Wähle eine Zuhörbank oder öffentliche Protokolle.', 'Jun asks for a lasting memory of open conversations. Choose a listening bench or public minutes.', 'Jun pide recordar las charlas abiertas. Elige banco de escucha o actas públicas.', 'Jun veut garder mémoire des échanges. Choisis un banc d’écoute ou des comptes rendus publics.', 'Джун попросит сохранить память открытых бесед. Выбери скамью слушания или общие протоколы.'), 'park', 38, 8, 380),
        step(tr('Die Stadt braucht keine letzte Rede', 'The city needs no final speech', 'La ciudad no necesita un discurso final', 'La ville n’a pas besoin d’un dernier discours', 'Городу не нужна последняя речь'), tr('Alle acht sitzen nach dem Nachtblütenfest zusammen. Selma schließt kein Gespräch endgültig; der nächste Alltag gehört ihnen weiter gemeinsam.', 'All eight sit together after the night bloom festival. Selma closes no conversation forever; everyday life remains their shared work.', 'Los ocho se reúnen tras la fiesta. Selma no cierra las conversaciones; la vida sigue siendo común.', 'Les huit se retrouvent après la fête. Selma ne clôt rien pour toujours ; le quotidien reste partagé.', 'Восемь соседей встретятся после праздника. Сельма не закроет разговор навсегда; будни останутся общей заботой.'), 'park', 56, 9, 42),
    ], tr('Selma hält Fragen und Antworten fest und lädt auch die stillen Nachbarn zum nächsten Gespräch ein.', 'Selma records questions and replies and invites quiet neighbours to the next conversation.', 'Selma registra preguntas y respuestas e invita a los vecinos callados.', 'Selma note questions et réponses et invite les voisins discrets.', 'Сельма записывает вопросы и ответы и приглашает тихих соседей.'), [
        ('listening_bench', tr('Die Zuhörbank erinnern', 'Remember the listening bench', 'Recordar el banco de escucha', 'Garder le banc d’écoute', 'Сохранить скамью слушания'), tr('Die Zuhörbank bleibt in Selmas Geschichte. Ein Gespräch darf klein beginnen, bevor es den ganzen Hof erreicht.', 'The listening bench stays in Selma’s story. A conversation may start small before reaching the whole court.', 'El banco queda en su historia. La charla empieza pequeña antes de llegar al patio.', 'Le banc reste dans son récit. Un échange peut commencer petit avant d’atteindre la cour.', 'Скамья останется в истории Сельмы. Беседа может начаться тихо, прежде чем дойти до двора.')),
        ('public_minutes', tr('Die öffentlichen Protokolle erinnern', 'Remember the public minutes', 'Recordar las actas públicas', 'Garder les comptes rendus publics', 'Сохранить общие протоколы'), tr('Die öffentlichen Protokolle bleiben Selmas Erinnerung. Zustimmung, Widerspruch und offene Fragen werden gemeinsam bewahrt.', 'The public minutes stay Selma’s memory. Agreement, disagreement and open questions are kept together.', 'Las actas quedan como recuerdo. Acuerdos, desacuerdos y preguntas se conservan juntos.', 'Les comptes rendus restent en mémoire. Accords, désaccords et questions restent ensemble.', 'Протоколы останутся памятью Сельмы. Согласие, несогласие и вопросы сохранятся вместе.')),
    ])

