def digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def append_unique(collection, proposed, identity):
    existing = {entry[identity]: entry for entry in collection}
    if len(existing) != len(collection):
        raise ValueError('Duplicate existing identities: ' + identity)
    for entry in proposed:
        key = entry[identity]
        if key in existing:
            if existing[key] != entry:
                raise ValueError('Refusing to overwrite existing content: ' + key)
        else:
            collection.append(entry)
            existing[key] = entry


def author():
    data = json.loads(PATH.read_text(encoding='utf-8-sig'))
    catalogs = {lang: json.loads((LOCALES / (lang + '.json')).read_text(encoding='utf-8-sig')) for lang in LANGUAGES}
    before, before_catalogs = copy.deepcopy(data), copy.deepcopy(catalogs)
    if data['version'] < 8:
        raise ValueError('Purple Garden expects the integrated seven-city catalog at v8 or later')
    if not set(SOURCES) <= {city['id'] for city in data['cities']}:
        raise ValueError('Purple Garden requires all seven existing campaign cities')
    added_texts = dict(TEXT)

    def text(key, value):
        if set(value) != set(LANGUAGES) or any(not v.strip() for v in value.values()):
            raise ValueError('Missing translation: ' + key)
        if key in added_texts and added_texts[key] != value:
            raise ValueError('Conflicting Purple Garden translation: ' + key)
        fields = lambda s: sorted(f for _, f, _, _ in string.Formatter().parse(s) if f is not None)
        if any(fields(value[lang]) != fields(value['de']) for lang in LANGUAGES):
            raise ValueError('Translation placeholder mismatch: ' + key)
        added_texts[key] = value
        return key

    source = [i for i in data['instances'] if i.get('cityId', 'burning_hills') == 'burning_hills']
    ids = {i['id']: 'pg_' + i['id'] for i in source}
    instances = [dict(copy.deepcopy(i), id=ids[i['id']], cityId=CITY, introducedVersion=VERSION) for i in source]
    routes = [dict(copy.deepcopy(r), id='pg_' + r['id'], **{'from': ids[r['from']], 'to': ids[r['to']]})
              for r in data['routes'] if r['from'] in ids and r['to'] in ids]
    foundation = {q['id']: q for q in data['quests'] if q.get('cityId') == 'seven_hills'}
    quests = []
    ready = tr('Alles bereit. Hole die Belohnung ab; danach gehen wir gemeinsam weiter.', 'Everything is ready. Claim the reward; then we continue together.', 'Todo listo. Recoge la recompensa y seguiremos juntos.', 'Tout est prêt. Récupère la récompense, puis nous continuerons.', 'Всё готово. Забери награду, и мы продолжим вместе.')
    for source_id, quest_id, title, body in MAIN_TEXT:
        q = copy.deepcopy(foundation['sh_' + source_id])
        q.update(id='pg_' + quest_id, cityId=CITY, focus=q['focus'].replace('sh_', 'pg_', 1),
                 titleKey=text('pg.quest.' + quest_id + '.title', title),
                 bodyKey=text('pg.quest.' + quest_id + '.body', body))
        for c in q['conditions']:
            if c['target'].startswith('sh_'):
                c['target'] = c['target'].replace('sh_', 'pg_', 1)
            if c['kind'] == 8 and quest_id in MAIN_POPULATIONS:
                c['count'] = MAIN_POPULATIONS[quest_id]
        text(q['bodyKey'] + '.dialogue', {lang: value.split(': ', 1)[-1] for lang, value in body.items()})
        text(q['bodyKey'] + '.dialogue_ready', ready)
        quests.append(q)

    def goal(kind, count, target=''):
        return dict(kind=kind, count=count, target=target, textKey='pg.goal.' + ('level' if kind == 0 else COUNTER_KEYS[kind]))

    stories = []
    for row in PEOPLE:
        pid, base = 'pg_' + row['id'], 'pg.story.' + row['id']
        p = dict(id=pid, cityId=CITY, residents=row['residents'], focus=ids[row['focus']], repeatDelaySeconds=300,
                 nameKey=text(base + '.name', tr(*([row['name']] * 5))), roleKey=text(base + '.role', row['role']),
                 biographyKey=text(base + '.biography', row['bio']), greetingKey=text(base + '.greeting', row['greeting']),
                 chapters=[], recurring=[])
        for index, chapter_row in enumerate(row['chapters']):
            key = base + '.chapter.' + str(index + 1)
            choices = []
            if index == 2:
                for value, label, outcome in CHOICES[row['id']]:
                    prefix = 'pg.choice.' + row['id'] + '.' + value
                    choices.append(dict(id=value, textKey=text(prefix, label), outcomeKey=text(prefix + '.outcome', outcome)))
            else:
                choices = [dict(id='help', textKey='pg.choice.help', outcomeKey='pg.outcome.help')]
            family = chapter_row['family']
            zone = 3 if family in ('butter_factory', 'supermarket', 'bakery') else 2 if family in ('park', 'residential_house') else 0 if family in ('cultivation_plot', 'farm_warehouse', 'farm_processing') else 1
            p['chapters'].append(dict(id=pid + '_chapter_' + str(index + 1),
                titleKey=text(key + '.title', chapter_row['title']), bodyKey=text(key + '.body', chapter_row['body']),
                memoryKey=text(key + '.memory', chapter_row['memory']), completedKey='pg.story.completed',
                residents=row['thresholds'][index], moneyReward=300 + index * 225, zone=zone,
                goals=[goal(0, chapter_row['level'], family), goal(chapter_row['counter'], chapter_row['count'])],
                choices=choices, prerequisites=[], itemRewards=[]))
        for index, (kind, count, zone, label) in enumerate(REPEATS):
            key = base + '.repeat.' + str(index + 1)
            title = {lang: row['name'].split()[0] + ': ' + label[lang] for lang in LANGUAGES}
            instruction = tr('Auftrag seit Annahme: {0}.', 'Task since acceptance: {0}.', 'Encargo desde la aceptación: {0}.', 'Mission depuis acceptation : {0}.', 'Задание после принятия: {0}.')
            repeat_body = text(key + '.body', {lang: row['repeat'][lang] + ' ' + instruction[lang].format(COUNTER_ACTION[kind][lang].format(count)) for lang in LANGUAGES})
            p['recurring'].append(dict(id=pid + '_repeat_' + str(index + 1), titleKey=text(key + '.title', title),
                bodyKey=repeat_body, completedKey='pg.repeat.completed', memoryKey='', residents=row['residents'],
                moneyReward=225, zone=zone, goals=[goal(kind, count)],
                choices=[dict(id='help', textKey='pg.choice.help', outcomeKey='pg.outcome.help')], prerequisites=[], itemRewards=[]))
        stories.append(p)

    projects = []
    for row in PROJECTS:
        pid, key = 'pg_joint_' + row['id'], 'pg.joint.' + row['id']
        participants = ['pg_' + id for id in row['participants']]
        quest = dict(id=pid, titleKey=text(key + '.title', row['title']), bodyKey=text(key + '.body', row['body']),
            memoryKey=text(key + '.memory', row['memory']), completedKey='pg.joint.completed', residents=row['residents'],
            moneyReward=1800, zone=row['zone'], goals=[goal(row['kind'], row['count'])],
            choices=[dict(id='together', textKey='pg.choice.help', outcomeKey='pg.outcome.help')],
            prerequisites=[id + '_chapter_1' for id in participants], itemRewards=[])
        projects.append(dict(id=pid, cityId=CITY, host=participants[0], participants=participants, quest=quest))

    city = dict(id=CITY, nameKey='city.purple_garden', scenePath='Assets/Weedtopia/Game/Scenes/PurpleGarden.unity',
        sourceCity='', unlockSources=SOURCES, introducedVersion=VERSION,
        unlockResidents=500000, bridgeMoney=12500, bridgeCards=7,
        invitationTitleKey='campaign.purple_garden_title', invitationBodyKey='campaign.purple_garden_body',
        invitationNoticeKey='campaign.purple_garden_notice', invitationLockedKey='campaign.purple_garden_locked', dialoguePrefix='pg.dialog.')
    for collection, entries in [('cities', [city]), ('instances', instances), ('routes', routes), ('quests', quests),
                                ('vipStories', stories), ('vipCollaborations', projects)]:
        append_unique(data[collection], entries, 'id')
    append_unique(data['texts'], [dict(key=key, de=value['de']) for key, value in added_texts.items()], 'key')
    data['version'] = max(data['version'], VERSION)
    for lang in LANGUAGES:
        append_unique(catalogs[lang]['entries'], [dict(key=key, value=value[lang]) for key, value in added_texts.items()], 'key')
    validate(data, catalogs)
    collections = {'cities', 'instances', 'routes', 'quests', 'vipStories', 'vipCollaborations', 'texts'}
    for collection in collections:
        for prior, current in zip(before[collection], data[collection][:len(before[collection])]):
            assert current == prior, collection
    for key in before.keys() - collections - {'version'}:
        assert data[key] == before[key], key
    for lang in LANGUAGES:
        for prior, current in zip(before_catalogs[lang]['entries'], catalogs[lang]['entries'][:len(before_catalogs[lang]['entries'])]):
            assert current == prior, lang
    changed = data != before or catalogs != before_catalogs
    # All authoring, localization, reference and preservation checks precede the first write.
    if data != before:
        PATH.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    for lang in LANGUAGES:
        if catalogs[lang] != before_catalogs[lang]:
            (LOCALES / (lang + '.json')).write_text(json.dumps(catalogs[lang], ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    receipt = dict(city=CITY, version=data['version'], changed=changed, instances=len(instances), routes=len(routes),
        mainQuests=len(quests), permanentResidents=len(stories), personalChapters=sum(len(p['chapters']) for p in stories),
        recurringVariants=sum(len(p['recurring']) for p in stories), communityProjects=len(projects),
        localizedKeys=len(added_texts), languages=list(LANGUAGES), oldContentDigest=digest(before), contentDigest=digest(data),
        priorContentPreserved=True, priorLocaleEntriesPreserved=True, placeholderParity=True, freshProgressGoals=True,
        residents=[dict(id=p['id'], appearsAt=p['residents'], chapters=[c['residents'] for c in p['chapters']]) for p in stories],
        projects=[dict(id=p['id'], residents=p['quest']['residents'], participants=p['participants'], goals=p['quest']['goals']) for p in projects])
    REPORT.parent.mkdir(parents=True, exist_ok=True)
    REPORT.write_text(json.dumps(receipt, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(receipt, ensure_ascii=False, indent=2))
    return receipt


def validate(data, catalogs):
    city = next(c for c in data['cities'] if c['id'] == CITY)
    assert city['unlockSources'] == SOURCES and city['unlockResidents'] == 500000
    assert city['bridgeMoney'] == 12500 and city['bridgeCards'] == 7 and city['introducedVersion'] == VERSION
    original = [i for i in data['instances'] if i.get('cityId', 'burning_hills') == 'burning_hills']
    instances = [i for i in data['instances'] if i.get('cityId') == CITY]
    instance_ids = {i['id'] for i in instances}
    assert len(instances) == 56 and sorted(i['family'] for i in instances) == sorted(i['family'] for i in original)
    assert all(i['introducedVersion'] == VERSION for i in instances)
    routes = [r for r in data['routes'] if r['from'] in instance_ids]
    assert len(routes) == 35 and all(r['to'] in instance_ids and r['from'] != r['to'] for r in routes)
    quests = [q for q in data['quests'] if q.get('cityId') == CITY]
    assert len(quests) == 18 and all(q['focus'] in instance_ids for q in quests)
    assert all(not str(c['target']).startswith(('lm_', 'sh_', 'br_', 'cv_', 'mw_')) for q in quests for c in q['conditions'])
    families = {i['family'] for i in instances} | {building['id'] for building in data['buildings']}
    for q in quests:
        for condition in q['conditions']:
            target = condition['target']
            assert not target or target in instance_ids | families | {'mila', 'jaro', 'nia', 'rocko'}, (q['id'], target)
            if condition['kind'] == 8 and q['id'][3:] in MAIN_POPULATIONS:
                assert condition['count'] == MAIN_POPULATIONS[q['id'][3:]]
    people = [p for p in data['vipStories'] if p['cityId'] == CITY]
    assert [p['id'] for p in people] == ['pg_' + p['id'] for p in PEOPLE]
    assert [p['residents'] for p in people] == [50, 120, 260, 500, 850, 1300, 1900, 2600]
    assert all(len(p['chapters']) == 4 and len(p['recurring']) == 3 and p['focus'] in instance_ids for p in people)
    families = {i['family'] for i in instances} | {'park', 'residential_house'}
    for person, row in zip(people, PEOPLE):
        thresholds = [c['residents'] for c in person['chapters']]
        assert thresholds[0] == person['residents'] and all(a < b for a, b in zip(thresholds, thresholds[1:]))
        assert len(person['chapters'][2]['choices']) == 2
        assert [c['id'] for c in person['chapters'][2]['choices']] == [c[0] for c in CHOICES[row['id']]]
        assert len(set(c['outcomeKey'] for c in person['chapters'][2]['choices'])) == 2
        assert person['repeatDelaySeconds'] == 300 and all(not q['memoryKey'] for q in person['recurring'])
        for q in person['chapters'] + person['recurring']:
            assert any(g['kind'] in COUNTER_KEYS for g in q['goals']) and all(g['count'] > 0 for g in q['goals'])
            assert all(g['target'] in families | instance_ids for g in q['goals'] if g['kind'] == 0)
    assert max(c['residents'] for p in people for c in p['chapters']) == 20000
    projects = [p for p in data['vipCollaborations'] if p['cityId'] == CITY]
    assert len(projects) == 3 and [p['quest']['residents'] for p in projects] == [2000, 6500, 12500]
    assert all(p['quest']['prerequisites'] == [id + '_chapter_1' for id in p['participants']] for p in projects)
    assert all(p['host'] in p['participants'] and set(p['participants']) <= {v['id'] for v in people} for p in projects)
    texts = {t['key']: t['de'] for t in data['texts']}
    required = set(TEXT)
    for q in quests:
        required.update([q['titleKey'], q['bodyKey'], q['bodyKey'] + '.dialogue', q['bodyKey'] + '.dialogue_ready'])
    for p in people:
        required.update(p[k] for k in ('nameKey', 'roleKey', 'biographyKey', 'greetingKey'))
        for q in p['chapters'] + p['recurring']:
            required.update(q[k] for k in ('titleKey', 'bodyKey', 'completedKey', 'memoryKey') if q[k])
            required.update(g['textKey'] for g in q['goals'])
            for choice in q['choices']:
                required.update([choice['textKey'], choice['outcomeKey']])
    for p in projects:
        required.update(p['quest'][k] for k in ('titleKey', 'bodyKey', 'memoryKey', 'completedKey'))
    fields = lambda s: sorted(f for _, f, _, _ in string.Formatter().parse(s) if f is not None)
    for lang in LANGUAGES:
        entries = {e['key']: e['value'] for e in catalogs[lang]['entries']}
        assert len(entries) == len(catalogs[lang]['entries']), lang
        assert all(k in entries and entries[k].strip() for k in required), lang
        assert all(fields(entries[k]) == fields(texts[k]) for k in required), lang
    assert required <= texts.keys()
    assert not any('Little Montana' in texts[k] or 'Seven Hills' in texts[k] for k in required if k.startswith('pg.'))


if __name__ == '__main__':
    author()

